class Solution {

public:
    vector<int> maxSumCombinations(vector<int> &nums1, vector<int> &nums2, int k) {
        sort(nums1.begin(), nums1.end(), greater<int>()); int i = 0;
        sort(nums2.begin(), nums2.end(), greater<int>()); int j = 0;

        unordered_set<string> visited;
        priority_queue<pair<int, pair<int, int>>> pq;
        vector<int> ans;


        pq.push({nums1[i] + nums2[j] , {i, j}});
        visited.insert({to_string(i) + "," + to_string(j)});
        while (k > 0 && !pq.empty()) {
            pair<int, pair<int, int>> currMaxPair = pq.top();
            pair<int, int> coords = currMaxPair.second;

            i = coords.first;
            j = coords.second;

            vector<pair<int, int>> nextCoords = {{i, j + 1}, {i + 1, j}};
            for (pair<int, int> nextCoord: nextCoords) {
                if (nextCoord.first < nums1.size() && nextCoord.second < nums2.size() && !visited.count(to_string(nextCoord.first) + "," + to_string(nextCoord. second))) {
                    pq.push({nums1[nextCoord.first] + nums2[nextCoord.second], {nextCoord.first, nextCoord. second}});
                    visited.insert({to_string(nextCoord.first) + "," + to_string(nextCoord.second)});
                }
            }

            ans.push_back(currMaxPair.first);
            pq.pop();
            k--;
        }
        return ans;
    }
};
